                            tax_rate_id: string;
                            discount?: {
                                /** @example 10 */
                                value?: number;
                                /**
                                 * @description Values between 0 and 100
                                 * @example percentage
                                 * @enum {string}
                                 */
                                type?: "percentage";
                            };
                            /** @example d905ff57-e866-0f59-9d1e-1fd4538bfae1 */
